def reference_reassign(raw_grid, resolution, origin, robot_name, robot_position, target, reserved_poses=(), blocked_positions=()):
    """Choose a fresh reachable pose when a delivered map invalidates one."""
    candidates = rally_pose_candidates(raw_grid, resolution, origin, target)
    traversable = traversable_grid(raw_grid, resolution, clearance_m=RALLY_PATH_CLEARANCE_M)
    best = None
    for pose in candidates:
        if any((math.dist((pose.x, pose.y), other) < RALLY_MIN_SEPARATION_M for other in reserved_poses)):
            continue
        plan = plan_rally_leg(pose, raw_grid, resolution, origin, robot_position, max_distance_m=float('inf'), blocked_positions=blocked_positions)
        if plan[0] is None:
            continue
        start = world_to_grid(robot_position[0], robot_position[1], resolution, origin[0], origin[1])
        start = navigation_start_cell(raw_grid, traversable, start, max(1, math.ceil(0.6 / resolution)))
        if start is None:
            continue
        distances = path_distance_grid(traversable, start)
        cell = world_to_grid(pose.x, pose.y, resolution, origin[0], origin[1])
        distance = distances[cell] if 0 <= cell[0] < traversable.shape[0] and 0 <= cell[1] < traversable.shape[1] else np.inf
        if not np.isfinite(distance):
            continue
        if best is None or distance < best[0]:
            best = (float(distance), pose)
    return None if best is None else best[1]
